WITH store_item_sales AS ( SELECT ss.ss_store_id, ss.ss_item_id, SUM(ss.ss_quantity) AS total_quantity FROM store_sales ss GROUP BY ss.ss_store_id, ss.ss_item_id ), item_reviews AS ( SELECT pr.pr_item_id, AVG(pr.pr_sentiment) AS avg_sentiment, COUNT(*) AS review_count FROM product_reviews pr GROUP BY pr.pr_item_id ), ranked_sales AS ( SELECT si.ss_store_id, si.ss_item_id, si.total_quantity, ROW_NUMBER() OVER (PARTITION BY si.ss_store_id ORDER BY si.total_quantity DESC) AS rank FROM store_item_sales si ) SELECT s.s_store_name, i.i_name, i.i_category, rs.total_quantity, ir.avg_sentiment, ir.review_count FROM ranked_sales rs JOIN stores s ON rs.ss_store_id = s.s_store_id JOIN items i ON rs.ss_item_id = i.i_item_id LEFT JOIN item_reviews ir ON i.i_item_id = ir.pr_item_id WHERE rs.rank <= 5 ORDER BY s.s_store_name, rs.rank
